"use strict";

// ez2-page-i18n.js — Ez2.PAGE 伺服器端多語系(2026-07-26,the maintainer 令「全面 i18n+設定頁可預定語系」)
//
// 四語系正本=設計 mock v43 語系選單(docs/design/ez2-page-frontend-mock.html:1857):
// 繁體中文 / English / 日本語 / 한국어 —— 順序與集合都照它,不自行增減。
//
// 設計紅線:
//   1. 零客戶端 JS —— 語系在伺服器端決定並渲染,不靠瀏覽器腳本切換(PAGE 速度分層鐵律)。
//   2. 純函式零依賴 —— 沒有 IO、沒有全域狀態,server 與 smoke 都用同一份。
//   3. 缺鍵 fail-loud —— 找不到鍵回 "!!key!!" 並可被 smoke 抓;絕不靜默回另一語言,
//      靜默回退會讓半套翻譯看起來像完成。
//   4. 鍵集必須四語齊平(parity)—— 由 auditDictionaries 機械驗證,不靠人肉檢查。
//
// 協商優先序(高→低):使用者明選(query ?lang=) > 已存偏好(cookie) > 瀏覽器 Accept-Language > 預設。
// query 最高是刻意的:使用者當下的明確動作永遠贏過舊偏好,且讓「設定頁選語系」立即可見。

const DEFAULT_LOCALE = "zh-TW";
const SUPPORTED_LOCALES = Object.freeze(["zh-TW", "en", "ja", "ko"]);
