function isSupported(locale) { return SUPPORTED_LOCALES.indexOf(String(locale || "")) >= 0; }

// 缺鍵不靜默:回 "!!key!!" 讓畫面與 smoke 都看得見(半套翻譯不得偽裝成完成)。
function t(locale, key, vars) {
  const table = DICT[isSupported(locale) ? locale : DEFAULT_LOCALE] || DICT[DEFAULT_LOCALE];
  const raw = Object.prototype.hasOwnProperty.call(table, key) ? table[key] : null;
  if (raw == null) return "!!" + key + "!!";
  if (!vars) return raw;
  return String(raw).replace(/\{(\w+)\}/g, (match, name) =>
    Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : match);
}

// Accept-Language 解析:回按 q 值排序的語言標籤(小寫)。
function parseAcceptLanguage(header) {
  return String(header || "")
    .split(",")
    .map((part) => {
      const [tag, ...params] = part.trim().split(";");
      const q = params.map((p) => p.trim()).find((p) => p.startsWith("q="));
      const weight = q ? Number(q.slice(2)) : 1;
      return { tag: String(tag || "").trim().toLowerCase(), q: Number.isFinite(weight) ? weight : 0 };
    })
    .filter((item) => item.tag && item.q > 0)
    .sort((a, b) => b.q - a.q)
    .map((item) => item.tag);
}

// zh 系一律給繁中(本產品只出繁中,不做簡繁轉換=不假裝支援簡體)。
function matchLocale(tag) {
  const lower = String(tag || "").toLowerCase();
  if (!lower) return null;
  if (lower.startsWith("zh")) return "zh-TW";
  if (lower === "en" || lower.startsWith("en-")) return "en";
  if (lower === "ja" || lower.startsWith("ja-")) return "ja";
  if (lower === "ko" || lower.startsWith("ko-")) return "ko";
  return null;
}

// 協商:query > cookie > Accept-Language > 預設。回 {locale, source} 讓呼叫端可稽核來源。
function negotiate(input = {}) {
  const fromQuery = matchLocale(input.query);
  if (fromQuery) return { locale: fromQuery, source: "query" };
  const fromCookie = matchLocale(input.cookie);
  if (fromCookie) return { locale: fromCookie, source: "cookie" };
  for (const tag of parseAcceptLanguage(input.acceptLanguage)) {
    const matched = matchLocale(tag);
    if (matched) return { locale: matched, source: "header" };
  }
  return { locale: DEFAULT_LOCALE, source: "default" };
}

function localeCookie(locale, options = {}) {
  const value = isSupported(locale) ? locale : DEFAULT_LOCALE;
  return LOCALE_COOKIE + "=" + value + "; Path=/; Max-Age=" + LOCALE_COOKIE_MAX_AGE +
    "; SameSite=Lax" + (options.secure ? "; Secure" : "");
}

// 機械驗證:四語鍵集必須完全相同、無空字串、佔位符對稱。
// 人肉檢查抓不到漏譯,這個抓得到;新增語系只要加進 SUPPORTED_LOCALES 就自動納管。
function auditDictionaries() {
  const problems = [];
  const base = Object.keys(DICT[DEFAULT_LOCALE]).sort();
  for (const locale of SUPPORTED_LOCALES) {
    const table = DICT[locale];
    if (!table) { problems.push("missing_dictionary:" + locale); continue; }
    const keys = Object.keys(table).sort();
    for (const key of base) if (keys.indexOf(key) < 0) problems.push("missing:" + locale + ":" + key);
    for (const key of keys) if (base.indexOf(key) < 0) problems.push("extra:" + locale + ":" + key);
    for (const key of keys) if (!String(table[key]).trim()) problems.push("empty:" + locale + ":" + key);
  }
  // 佔位符對稱:同一鍵在各語言必須用同一組 {vars},否則會渲染出殘留的 {name}
  for (const key of base) {
    const expected = (String(DICT[DEFAULT_LOCALE][key]).match(/\{(\w+)\}/g) || []).sort().join(",");
    for (const locale of SUPPORTED_LOCALES) {
      if (!DICT[locale]) continue;
      const actual = (String(DICT[locale][key] || "").match(/\{(\w+)\}/g) || []).sort().join(",");
      if (actual !== expected) problems.push("placeholder:" + locale + ":" + key);
    }
  }
  // 語系標籤必須齊全(選單缺標籤=使用者選不到那個語系)
  for (const locale of SUPPORTED_LOCALES) {
    if (!String(LOCALE_LABELS[locale] || "").trim()) problems.push("missing_label:" + locale);
  }
  return { ok: problems.length === 0, problems: [...new Set(problems)].sort(), key_count: base.length, locales: SUPPORTED_LOCALES.slice() };
}

module.exports = {
  DEFAULT_LOCALE,
  SUPPORTED_LOCALES,
  LOCALE_COOKIE,
  LOCALE_COOKIE_MAX_AGE,
  LOCALE_LABELS,
  DICT,
  isSupported,
  t,
  parseAcceptLanguage,
  matchLocale,
  negotiate,
  localeCookie,
  auditDictionaries
};
